create extension if not exists "pgcrypto"; create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null,age int,grade text,goal text,level text default 'beginner',locale text default 'ru',theme text default 'light',xp int default 0,streak int default 0,created_at timestamptz default now()); create table if not exists subjects(id text primary key,name text,icon text); create table if not exists topics(id uuid primary key default gen_random_uuid(),subject_id text references subjects(id),name text,position int default 0); create table if not exists user_subjects(user_id uuid references auth.users(id) on delete cascade,subject_id text references subjects(id),progress int default 0,primary key(user_id,subject_id)); create table if not exists questions(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,subject_id text,topic_id uuid,prompt text,type text,options jsonb,correct_answer text,explanation text,difficulty text); create table if not exists answers(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,question_id uuid,answer text,correct boolean,feedback text); create table if not exists tests(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,subject_id text,topic_id uuid,title text,question_count int); create table if not exists test_questions(test_id uuid,question_id uuid,position int,primary key(test_id,question_id)); create table if not exists test_results(id uuid primary key default gen_random_uuid(),test_id uuid,user_id uuid references auth.users(id) on delete cascade,score int,correct_count int,time_seconds int); create table if not exists ai_conversations(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,title text,subject_id text,created_at timestamptz default now()); create table if not exists ai_messages(id uuid primary key default gen_random_uuid(),conversation_id uuid,role text,content text,created_at timestamptz default now()); create table if not exists study_plans(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,title text,items jsonb); create table if not exists study_sessions(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,subject_id text,minutes int,xp int,created_at timestamptz default now()); create table if not exists achievements(id uuid primary key default gen_random_uuid(),code text unique,title text,description text,xp int); create table if not exists user_achievements(user_id uuid,achievement_id uuid,earned_at timestamptz default now(),primary key(user_id,achievement_id)); create table if not exists subscriptions(user_id uuid primary key,status text default 'free',provider text,customer_id text,subscription_id text,current_period_end timestamptz); create table if not exists usage_limits(user_id uuid primary key,ai_messages_used int default 0,ai_messages_limit int default 30,photos_used int default 0,photos_limit int default 5); alter table profiles enable row level security; create policy "own profile" on profiles for all using(auth.uid()=id) with check(auth.uid()=id); insert into subjects values('math','Математика','∑'),('english','Английский','A'),('cs','Информатика','</>'),('physics','Физика','⚛'),('chemistry','Химия','⚗'),('biology','Биология','🧬'),('russian','Русский','АБ'),('history','История','⌛') on conflict do nothing;